"""Cross-file runtime builder projection contracts for scan_project_sources()."""
from .common import *
from .ast_relations import grouped_relations

def project_clauses(stages,extra):
 stages=[*stages,
 S('builder_tokens',"SELECT __path,id AS node,attr AS name FROM attributes WHERE object_text='RuntimeBuilderName' UNION SELECT n.__path,n.id,s.value FROM nodes n JOIN string_values s ON s.__path=n.__path AND s.__start=n.__start AND s.__end=n.__end WHERE s.value!=''",('__path','node')),
 S('semantic_builders',"SELECT DISTINCT token.name FROM contexts c JOIN direct_sinks sink ON sink.__path=c.__path AND sink.fn=c.id AND sink.kind='runtime_sequence_projection' JOIN body_nodes body ON body.__path=c.__path AND body.fn=c.id JOIN nodes comparison ON comparison.__path=body.__path AND comparison.id=body.node AND comparison.kind='comparison_operator' JOIN nodes operand ON operand.__path=comparison.__path AND operand.parent=comparison.id JOIN builder_tokens token ON token.__path=operand.__path AND token.node=operand.id WHERE EXISTS(SELECT 1 FROM attributes spec WHERE spec.__path=comparison.__path AND spec.parent=comparison.id AND spec.object_text='spec' AND spec.attr='builder_name')",('name',)),
 S('builder_sites',"SELECT c.__path,c.id AS node,token.name FROM calls c JOIN arguments arg ON arg.__path=c.__path AND arg.call=c.id AND arg.position=1 JOIN builder_tokens token ON token.__path=arg.__path AND token.node=arg.id WHERE c.callee='runtime_builder_post_op' OR c.callee='RuntimeBuilderSpec' AND NOT EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='builder_name') UNION SELECT c.__path,c.id,token.name FROM calls c JOIN keywords k ON k.__path=c.__path AND k.call=c.id AND k.name='builder_name' JOIN builder_tokens token ON token.__path=k.__path AND token.node=k.value WHERE c.callee='RuntimeBuilderSpec' OR c.callee='runtime_builder_post_op' AND NOT EXISTS(SELECT 1 FROM arguments a WHERE a.__path=c.__path AND a.call=c.id AND a.position=1)",('__path','node','name')),
 S('project_seeds',"SELECT b.__path,b.fn,b.node,'builder' AS kind,0 AS priority FROM body_nodes b JOIN builder_sites site ON site.__path=b.__path AND site.node=b.node JOIN semantic_builders semantic ON semantic.name=site.name UNION SELECT b.__path,b.fn,c.id,'builder',1 FROM body_nodes b JOIN calls c ON c.__path=b.__path AND c.id=b.node WHERE NOT EXISTS(SELECT 1 FROM call_graph g WHERE g.__path=b.__path AND g.fn=b.fn AND g.node=c.id) AND EXISTS(SELECT 1 FROM contexts helper JOIN body_nodes own ON own.__path=helper.__path AND own.fn=helper.id JOIN builder_sites site ON site.__path=own.__path AND site.node=own.node JOIN semantic_builders semantic ON semantic.name=site.name WHERE helper.name=c.callee) UNION SELECT __path,fn,node,'semantic',0 FROM direct_sinks WHERE kind='runtime_semantic_projection'",('__path','fn','kind')),
 S('project_sinks',"WITH RECURSIVE sink(__path,fn,node,kind,priority,route) AS (SELECT __path,fn,node,kind,priority,'|'||fn||'|' FROM project_seeds UNION ALL SELECT g.__path,g.fn,s.node,s.kind,s.priority,s.route||g.fn||'|' FROM sink s JOIN call_graph g ON g.__path=s.__path AND g.target=s.fn WHERE instr(s.route,'|'||g.fn||'|')=0 AND NOT EXISTS(SELECT 1 FROM project_seeds direct WHERE direct.__path=g.__path AND direct.fn=g.fn AND direct.kind=s.kind)) SELECT __path,fn,node,kind FROM (SELECT s.*,row_number() OVER(PARTITION BY s.__path,s.fn,s.kind ORDER BY length(s.route),s.priority,n.__start) AS chosen FROM sink s JOIN nodes n ON n.__path=s.__path AND n.id=s.node) WHERE chosen=1",('__path','fn','kind'))]
 query="SELECT n.__path AS path,n.__start AS start_byte,n.__end AS end_byte,'SPT-028' AS issue,c.id AS identity,'project-builder' AS detector FROM contexts c JOIN project_sinks s ON s.__path=c.__path AND s.fn=c.id AND s.kind='builder' JOIN nodes n ON n.__path=s.__path AND n.id=s.node WHERE c.planning AND NOT EXISTS(SELECT 1 FROM project_sinks semantic WHERE semantic.__path=c.__path AND semantic.fn=c.id AND semantic.kind='semantic')"
 result=grouped_relations('state-flow-project',stages,[(('scan_project_sources',),query,query)],[],extra)
 enabled={'$option':'entryPoint','cases':{'scan_project_sources':TRUE},'default':FALSE}
 for clause in result:
  clause['relational']['partitionBy']='repository'
  for relation in clause['relational']['inputs'].values():
   ast=relation['evidence']['query']['ast'];ast['rule']=A(enabled,ast['rule'])
 return result
